-- 4) courses (151 รายวิชา)
INSERT INTO courses (course_code, name_th, name_en, credits, description_th, description_en, is_active, created_at, updated_at) VALUES
  ('CSC200', 'นวัตกรรมและการคอมพิวเตอร์ด้วยความรับผิดชอบ', 'Innovation and Responsible Computing', 3, 'การประดิษฐ์และนวัตกรรม เป้าหมายการพัฒนาอย่างยั่งยืนขององค์กรสหประชาชาติ การคอมพิวเตอร์ด้วยความรับผิดชอบ วิสาหกิจสังคม นวัตกรรมตัวแบบธุรกิจ กระบวนการคิดเชิงออกแบบ แผ่นผ้าเขียนภาพตัวแบบธุรกิจ แผ่นผ้าเขียนภาพประพจน์มูลค่า ต้นแบบ ผลิตภัณฑ์ขั้นต่ำที่มีศักยภาพทางการตลาดการวิเคราะห์ผลกระทบ', 'Invention and innovation, UN’s Sustainable Development Goals, responsible computing, social enterprises, business model innovation, design thinking, business model canvas, value proposition canvas, prototype, minimum viable product, impact analysis', true, now(), now()),
  ('CSC233', 'รูปแบบการโปรแกรม', 'Programming Paradigms', 2, 'ความรู้เบื้องต้นเกี่ยวกับภาษาในการเขียนโปรแกรม วิวัฒนาการของภาษา ไวยากรณ์ และความหมายการเขียนโปรแกรมเชิงโครงสร้าง โครงสร้างภาษาต่างๆ การใช้ภาษา (คอมไพเลอร์และอินเทอร์พริเตอร์) การแยกวิเคราะห์ และความกำกวม ตัวสร้างไวยากรณ์ ตัวแยกวิเคราะห์ และตัวจดจำ Backus-Naur Form (BNF) ไวยากรณ์ปกติ (RG) และนิพจน์ การวิเคราะห์คำออโตมาตาแบบ FA และ PDA ไวยากรณ์แอตทริบิวต์ (AG) กระบวนทัศน์การเขียนโปรแกรมในรูปแบบต่างๆ ภาษาโปรแกรมพื้นฐานและเครื่องมือ (R, Python, Racket และ Prolog) การกำหนดการจัดเก็บ และประเภทของข้อมูล การกำหนดขอบเขตแบบไดนามิกและแบบคงที่และการส่งผ่านพารามิเตอร์', 'Introduction to programming languages, historical evolution, and their syntax and semantics, structured programming, different language constructs, language implementation (compiler and interpreter), parsing and ambiguity, grammar generator, parsers and recognizers, Backus-Naur Form (BNF), regular grammar (RG) and expressions, lexical analyses, finite automata (FA), push-down automata (PDA), attribute grammars (AG), different programming paradigms (i.e., imperative, functional, and logic, as well as procedural, object oriented, and scripting), basic programming languages and tools (R, Python, Racket, and Prolog), storage and type bindings, dynamic and static scoping, and parameter passes.', true, now(), now()),
  ('CSC234', 'การพัฒนาแอปพลิเคชันบนอุปกรณ์พกพาโดยมีผู้ใช้เป็นศูนย์กลาง', 'User-Centered Mobile Application Development', 3, 'การเขียนโปรแกรมระบบเชิงโต้ตอบบนอุปกรณ์พกพาเบื้องต้น แพลตฟอร์มเชิงโต้ตอบสมัยใหม่พื้นฐานการพัฒนาซอฟต์แวร์โดยมีมนุษย์เป็นศูนย์กลาง พฤติกรรมมนุษย์ การออกแบบและทดสอบโดยมีผู้ใช้เป็นศูนย์กลาง การออกแบบการปฏิสัมพันธ์ การร่วมมือกันและการสื่อสาร ปัจจัยด้านมนุษย์กับความมั่นคงแพลตฟอร์มพกพา การออกแบบและพัฒนาแอปพลิเคชันบนอุปกรณ์พกพา', 'Introduction to programming mobile interactive systems, modern interactive platforms, foundations of human-centered software development, human behavior, usability, user- centered design and testing, designing interactions, collaboration and communication, human factors and security, mobile platforms, mobile application design and development.', true, now(), now()),
  ('CSC332', 'วิทยาการการรู้เบื้องต้น', 'Introduction to Cognitive Science', 3, 'บทนำ วิทยาการการรู้ตามวิธีการเชิงสหวิทยาการ การศึกษาจิตของมนุษย์ ความท้าทายและความซับซ้อน การบูรณาการทฤษฎีจากสาขาปรัชญา จิตวิทยา ภาษาศาสตร์ ประสาทวิทยาศาสตร์ มานุษยวิทยาและปัญญาประดิษฐ์ การรับรู้ของมนุษย์ กระบวนการของจิต และวิธีการคอมพิวเตอร์เพื่อจำลองกระบวนการเหล่านี้', 'Introduction, cognitive science as an interdisciplinary approach, theories involving the study of human mind, challenges and complexity, integration of theories from philosophy, psychology, linguistics, neuroscience, anthropology, and artificial intelligence fields, human cognition, processes of mind, and computational methods used to model these processes.', true, now(), now()),
  ('CSC335', 'คอมพิวเตอร์กราฟิกส์', 'Computer Graphics', 3, 'คอมพิวเตอร์กราฟิกส์เบื้องต้น พื้นฐานขั้นตอนวิธีสำหรับรูปทรงทั้งแบบ 2 มิติ และ 3 มิติ ปฏิสัมพันธ์การสร้างรูปทรงด้วยโอเพนจีแอลแบบทันเวลา การมองเชิงไปป์ไลน์ การสร้างรูปเรขาคณิต 3 มิติ การย้ายตำแหน่ง การตั้งโมเดลกล้อง การให้แสง การส่องแสงและการสร้างพิกเซล', 'Introduction to computer graphics, fundamental algorithms for two- and three- dimensional graphics, interactive, real-time rendering applications using Open Graphic Library (OpenGL), viewing pipeline, 3D geometry creation, transformations, the camera model, illumination, projections, and rasterization.', true, now(), now()),
  ('CSC344', 'โมเดลเพื่อการวิเคราะห์และตัดสินใจในระบบธุรกิจ', 'Analytic and Decision Models in Business Systems', 3, 'ระบบธุรกิจและกระบวนการตัดสินใจ กรอบการวิเคราะห์เชิงธุรกิจ การวิเคราะห์เชิงพรรณนา การจัดหาข้อมูลและความชาญฉลาดในข้อมูล การจัดการสมรรถนะธุรกิจและสคอร์การ์ดสำหรับการริเริ่ม สถิติและการแสดงภาพสำหรับการรายงานธุรกิจ การวิเคราะห์เชิงพยากรณ์ การคาดการณ์เชิงอนุมาน การทำเหมืองข้อมูล การทำเหมืองเว็บ/ข้อความ การวิเคราะห์เชิงบัญญัติ การโมเดลจำลองสถานการณ์ ต้นไม้เพื่อการตัดสินใจและการจัดการความรู้', 'Business system and decision processes, framework of business analytic models, descriptive analytics, data acquisition and intelligence, business performance management and scorecard for initiatives, statistics and visualization for business reporting, predictive analytics, regression, data mining, web/text mining, prescriptive analytics, simulation, decision tree and knowledge management.', true, now(), now()),
  ('CSC371', 'ระบบแบบกระจายและการประมวลผลแบบขนานเบื้องต้น', 'Introduction to Distributed Systems and Parallel Computing', 3, 'รายวิชานี้มุ่งให้ความรู้เบื้องต้นเกี่ยวกับระบบแบบกระจาย ซึ่งครอบคลุมถึงลักษณะการคำนวณแบบขนาน และแบบกระจาย ความรู้พื้นฐานทางด้านระบบ เช่น ภาวะพร้อมกัน และการเรียกใช้คำสั่งแบบขนานความต้องกัน และเวลาแฝง หลักการสำคัญของระบบแบบกระจาย เช่น การสื่อสาร กระบวนการ การประสานเวลา ความต้องกัน และการทำซ้ำ ความทนทานต่อความผิดพร่อง และความมั่นคง รวมถึงตัวอย่างที่ใช้งานได้จริง', 'Introduction and overview to concepts of distributed systems, including the aspect of parallel and distributed computing, fundamental system concepts such as concurrency and parallel execution, consistency, latency, key principles of distributed systems such as communication, processes, synchronization, consistency and replication, fault tolerance, security and practical examples, parallel computing, parallelization, basic parallel algorithms, analysis and programming.', true, now(), now()),
  ('CSC536', 'ความรู้เบื้องต้นเกี่ยวกับการประมวลผลภาพและการแสดงภาพ', 'Introduction to Image Processing and Visualization', 3, 'ความรู้เบื้องต้นเกี่ยวกับการประมวลผลภาพดิจิทัล หลักการพื้นฐาน และเทคนิคของคอนโวลูชันโดเมนเชิงพื้นที่เวลา และความถี่ ระดับสีเทา และไบนาไรเซซัน แบบจำลองสี การปรับปรุงภาพ การตรวจจับขอบ และค่าเกณฑ์ การแบ่งส่วนภาพ และการประยุกต์ใช้การประมวลผลภาพดิจิทัล เครื่องมือต่างๆ เช่น', 'Python และ OpenCV ความรู้เบื้องต้นเกี่ยวกับข้อมูลที่ใช้ในวิทยาการข้อมูลข้อมูลและความรู้ด้านภาพ สัญลักษณ์ และบริบททางภาพ หลักการและเทคนิคของการออกแบบที่ดี ทัศนศิลป์ และวิทยาการทางปัญญา การสร้างภาพข้อมูลเชิงสำรวจ และเชิงอธิบาย การวิเคราะห์ข้อมูลเชิงสำรวจ (EDA) การแสดงภาพข้อมูล สำหรับข้อมูลเชิงลึก การนำเสนอ และการตัดสินใจ การแสดงภาพข้อมูลในภาษาโปรแกรมและไลบรารี หรือ แพ็คเกจที่เกี่ยวข้อง เช่น R, Python และ Orange Basic introduction to digital image processing, basic principles and techniques of convolution and filtering, spatial, time and frequency domains, grayscale and binarization, color models, image enhancement, edge detection and thresholding, image segmentation, and applications of digital image processing, image processing tools, such as Python and OpenCV, basic introduction to data used in data science, visual information and knowledge, visual cues and contexts, principles and techniques of good designs, visual art and cognitive science, exploratory and explanatory visualizations, exploratory data analysis (EDA), data visualizations for insights, presentations and decision making, data visualizations in programming languages and their related libraries or packages, such as R, Python and Orange', true, now(), now()),
  ('CSC561', 'การประมวลผลการเงินและวิศวกรรมการเงินเบื้องต้น', 'Introduction to Computational Finance and Financial Engineering', 3, 'สถิติ พีชคณิตเมตริกซ์ การคำนวณผลตอบแทนจากสินทรัพย์ ทฤษฏีกองทุน แบบจำลองดรรชนีแบบจำลองการกำหนดราคาสินทรัพย์ทุน การวิเคราะห์ประสิทธิภาพการลงทุน วิธีการออปติไมซ์ข้อจำกัดแบบเท่าเทียม และไม่เท่าเทียม การตัดสินใจหลักด้านการเงิน การป้องกันความเสี่ยง ปัญหาการกำหนดราคา การสร้างแบบจำลองทางคณิตศาสตร์ เทคนิคทางตัวเลข และคอมพิวเตอร์เพื่อแบบจำลองใหม่ๆ', 'Statistics, matrix algebra, asset return calculations, portfolio theory, index models, the capital asset pricing model CAPM), investment performance analysis. Optimization methods involving equality and inequality constraints. Major decision in Finance, hedging, pricing problems. Formulation of mathematical models, numerical and computational techniques for arising models.', true, now(), now()),
  ('DSI106', 'ศิลปะดิจิทัล', 'Digital Arts', 3, 'การใช้เทคโนโลยีดิจิทัลในการสร้างสรรค์ การนำเสนอผลงาน และการสื่อสารไปยังกลุ่มเป้าหมายหลักการออกแบบสื่อ การออกแบบ สตอรี่บอร์ด และการประยุกต์ใช้เทคโนโลยีด้านกราฟิกส์ อาทิ ความเป็นจริงเสมือน ความเป็นจริงเสริม และ ภาพสามมิติ เป็นต้น', 'Using digital technology to create media, present and communicate to target audiences, principles of media design, storyboard design, and application of computer graphic technologies such as virtual reality (VR), augmented reality (AR) and 3D.', true, now(), now()),
  ('DSI111', 'การเปลี่ยนแปลงสู่ดิจิทัล', 'Digital Transformation', 3, 'สภาพแวดล้อมทางธุรกิจที่เปลี่ยนแปลงไปเนื่องจากเทคโนโลยีดิจิทัล การเกิดโมเดลธุรกิจใหม่ ๆ จากนวัตกรรมที่สร้างจากเทคโนโลยีดิจิทัล การเปลี่ยนแปลงโครงสร้างของต้นทุนและรายได้ ซึ่งมีผลมาจากการสร้างมูลค่าเพิ่มให้กับสิ่งที่ไม่มีตัวตน เช่น ข้อมูลส่วนบุคคล ข้อมูล การใช้งานในรูปแบบต่าง ๆ', 'How business eco-systems have transformed because of digital technologies, how new business models are formed by innovations from digital technologies, changes in cost structure and revenue from adding value to intangible goods such as personal information, financial data and various patterns of service usages.', true, now(), now()),
  ('DSI112', 'การออกแบบบริการดิจิทัล', 'Digital Service Design', 3, 'แนวคิดและหลักการการออกแบบบริการดิจิทัล เพื่อสร้างประสบการณ์การใช้งานที่ดีให้แก่ผู้ใช้ โดยการเลือกเทคโนโลยีและเอพีไอที่เหมาะสมมาใช้ในการออกแบบและพัฒนาได้ รวมไปถึงการนำทฤษฎีด้านการออกแบบกราฟิกส์มาใช้เพื่อเพิ่มความน่าสนใจให้กับบริการดิจิทัลด้วย', 'Concepts and principles of digital-service design in order to create a good user experience, how to select appropriate technologies and APIs, and how to use graphic design theory to make digital services more attractive.', true, now(), now()),
  ('DSI113', 'การจัดการความรู้', 'Knowledge Management', 3, 'ความรู้และการจัดการความรู้ การแบ่งปันความรู้ ความรู้ในบริบทขององค์กร ธุรกิจ การเคลื่อนไหลของความรู้ กระบวนการจัดการความรู้ กลยุทธ์การจัดการความรู้ การเลือกวิธีการจัดการความรู้และวิธีการจัดการความรู้ในยุคดิจิทัล', 'Knowledge and knowledge management, knowledge sharing, knowledge in term of organization and business, knowledge transfer, a process and strategy to manage the knowledge, selecting an appropriate knowledge management technique, knowledge management techniques in the digital era.', true, now(), now()),
  ('DSI117', 'การวิเคราะห์ข้อมูลเพื่อธุรกิจ', 'Business Analytics', 3, 'ความรู้เบื้องต้นเกี่ยวกับการวิเคราะห์ธุรกิจครอบคลุมเครื่องมือทางสถิติเชิงการจัดการในการวิเคราะห์เชิงพรรณนาและการวิเคราะห์เชิงคาดการณ์ รวมถึงการถดถอย การพยากรณ์ การวิเคราะห์ความเสี่ยง การจำลอง และการทำเหมืองข้อมูล และการวิเคราะห์การตัดสินใจ แนวคิดพื้นฐานและเครื่องมือที่จำเป็นวิธีการใช้เครื่องมือวิเคราะห์ธุรกิจขั้นพื้นฐานด้วยสเปรดชีต และวิธีสื่อสารกับผู้เชี่ยวชาญด้านการวิเคราะห์เพื่อใช้และตีความโมเดลการวิเคราะห์อย่างมีประสิทธิภาพ เน้นการใช้งาน แนวคิด และการตีความผลลัพธ์มากกว่าทฤษฎีและการคำนวณ ใช้โปรแกรมสำเร็จรูป คอมพิวเตอร์ในการวิเคราะห์ข้อมูล', 'An introduction to Business Analytics, covering managerial statistical tools in descriptive and predictive analytics, including regression, forecasting, risk analysis, simulation, and data mining Decision analysis basic concepts and necessary tools. How to use basic business analytics tools in a spreadsheet environment and how to communicate with analytics professionals to effectively use and interpret analytical models. Emphasise on the use, concepts and interpretation of results rather than theory and calculations. Computer software packages are used to analyze data.', true, now(), now()),
  ('DSI205', 'การตลาดดิจิทัล', 'Digital Marketing', 3, 'ศึกษาแนวคิดและหลักการพื้นฐานทางการตลาด การพัฒนาคุณลักษณะของลูกค้าเป้าหมาย (Customer Persona) การวิเคราะห์ข้อมูลความต้องการเชิงลึก กลยุทธ์การตลาด ส่วนผสมทางการตลาดสำหรับการโฆษณาและประชาสัมพันธ์ การตลาดคอนเทนต์ แพลตฟอร์มการตลาดออนไลน์และออฟไลน์รวมถึงอี-คอมเมิร์ช', 'This course provides the basics of marketing, including customer persona development, market research for insight finding, marketing strategy, content and social marketing and the marketing mix. It covers both online and offline platforms, including e- commerce.', true, now(), now()),
  ('DSI206', 'การวิจัยการตลาด', 'Marketing Research', 3, 'ศึกษาบริบท ความต้องการ และแนวโน้มการเปลี่ยนแปลงของผู้บริโภคในตลาดดิจิทัล ประเภทและรูปแบบของการวิจัยตลาดดิจิทัล กระบวนการกำหนดปัญหา วัตถุประสงค์ การออกแบบวิธีการวิจัย การค้นคว้าแหล่งขอ้มูล การสุ่มตัวอย่าง การกำหนดขนาดของกลุ่มตัวอย่าง การวัดทัศนคติของผู้บริโภค ความน่าเชื่อถือ การวิเคราะห์ข้อมูล การประยุกต์ใช้เครื่องมือดิจิทัลในการวิจัยตลาด และการจัดทำรายงานการตลาดดิจิทัล', 'Studying the consumer trends, needs and context in the digital marketplace. Types and models of digital market research, problem-designing process, objective, research design method, information searching, random sampling, size of the sample, consumer attitudes measurement, reliability, data analysis, application of digital tools in market research, and how to do digital marketing report.', true, now(), now()),
  ('DSI207', 'การบริหารงานบุคคล', 'Personnel Management', 3, 'ศึกษาแนวความคิดในการบริหารงานบุคคล นโยบายการบริหารงานบุคคล บทบาทและหน้าที่ของผู้บริหาร และกระบวนการบริหารงานบุคคล ตั้งแต่การวิเคราะห์งาน การวางแผนกำลังคน การสรรหาและคัดเลือกบุคคล การฝึกอบรมและพัฒนา การประเมินผลการปฏิบัติงานจนถึงการพัฒนาความก้าวหน้าในอาชีพของพนักงาน ค่าตอบแทน ความมั่นคงและความปลอดภัยของพนักงาน รวมทั้งระบบข้อมูลการบริหารงานบุคคล', 'The study of the concept of personnel management, the policy of personnel management, roles and functions of the manager and personnel management process from job analysis, personnel planning, recruiting and selection, training and development, performance appraisal, career development, compensation, maintenance of employee''s security and safety, including personnel information systems.', true, now(), now()),
  ('DSI208', 'เศรษฐศาสตร์ธุรกิจ', 'Business Economics', 3, 'ศึกษาทฤษฎีพฤติกรรมผู้บริโภค อุปสงค์และอุปทานของบุคคลและตลาด ทฤษฎีการผลิต การตัดสินใจเลือกใช้ปัจจัยการผลิตอย่างมีประสิทธิภาพ ทฤษฎีต้นทุนการผลิตทั้งในระยะสั้นและระยะยาว การกำหนดราคาของผู้ผลิตในตลาดประเภทต่าง ๆ และกรณีศึกษาการประยุกต์ใช้แนวคิดทางเศรษฐศาสตร์ในภาคธุรกิจ', 'Theory of consumer behavior, individual and market demand-supply, theory of production, decision-making using efficient inputs, short-term and long-term production cost theory, and price determination.', true, now(), now()),
  ('DSI209', 'การจัดการการเงิน', 'Financial Management', 3, 'ศึกษาแนวคิดและทฤษฎีทางการบริหารการเงิน องค์ประกอบตลาดเงินและตลาดทุน แนวคิดบัญชีและต้นทุน การนำเครื่องมือการบริหารการเงินมาใช้ในการวิเคราะห์ข้อมูลด้านการเงินเพื่อการควบคุมและวัดผลการดำเนินธุรกิจ', 'Basic concepts and theory of financial management, the components of money market and capital markets. Using financial management tools to analyse financial data to control and measure the business operations.', true, now(), now()),
  ('DSI210', 'การบัญชีสำหรับธุรกิจขนาดเล็กและขนาดกลาง', 'Accounting for Small and Medium Enterprises', 3, 'ศึกษาเกี่ยวกับทฤษฎีเบื้องต้นและหลักการทางการบัญชี แบบฟอร์มรายงานการเงินและการวิเคราะห์งบการเงิน การวิเคราะห์การทำกำไร วิเคราะห์และเปรียบเทียบแหล่งที่มาและใช้ไปของเงินทุน ศึกษาเปรียบเทียบระหว่างการบัญชีต้นทุนและบัญชีการเงิน ประเภทของงบประมาณ และการพยากรณ์การขาย', 'Basic accounting concepts and principles, forms of financial statement and analysis of financial statements. Income measurements, valuation problems, analysis of sources and use of fund. Comparison between cost accounting and financial accounting. Types of budgets, illustration of master budget, sale forecasting.', true, now(), now()),
  ('GEN111', 'มนุษย์กับหลักจริยศาสตร์เพื่อการดำเนินชีวิต', 'Man and Ethics of Living', 3, 'รายวิชานี้มุ่งสอนแนวคิดในการดำเนินชีวิตและแนวทางในการทำงาน ตามแบบอย่างที่ดีที่เป็นแนวทางการปฏิบัติของสิ่งที่มหาวิทยาลัยเทคโนโลยีพระจอมเกล้าธนบุรีได้ตั้งเป้าหมายในการพัฒนาให้บัณฑิตของมหาวิทยาลัยเป็นบัณฑิตที่เก่งและดี และมีจรรยาบรรณในวิชาชีพ ตลอดจนปลูกฝังให้นักศึกษาเข้าใจถึงวิสัยทัศน์และเป้าหมายของมหาวิทยาลัยเทคโนโลยีพระจอมเกล้าธนบุรี โดยจัดการเรียนการสอนแบบบูรณาการ องค์ความรู้ เพื่อสร้างทัศนคติที่ดีต่อการทำประโยชน์เพื่อส่วนรวม ความเป็นพลเมือง และนำความรู้และความถนัดในวิชาชีพของตนไปใช้ในการพัฒนาตนเองตลอดระยะเวลาที่ศึกษาอยู่ในมหาวิทยาลัยและสืบต่อเนื่องไปถึงการดำเนินชีวิตเพื่อประโยชน์แห่งตนเองและผู้อื่น เพื่อให้บัณฑิตมีคุณลักษณะที่พึงประสงค์ตามวิสัยทัศน์ของมหาวิทยาลัยเทคโนโลยีพระจอมเกล้าธนบุรี', 'This course studies the concept of living and working based on KMUTT’s Mission to develop its students to be the best academically, to have morality and work ethics, and to demonstrate the KMUTT vision and mission through the use of knowledge and integrative learning approaches. Students will be able to gain KMUTT’s desirable vision of the University such as, social responsibility, KMUTT Citizenship, professional skills, and to apply knowledge toward life in KMUTT and beyond for the benefit of themselves and others.', true, now(), now()),
  ('GEN121', 'ทักษะการเรียนรู้และการแก้ปัญหา', 'Learning and Problem Solving Skills', 3, 'วิชานี้เน้นการพัฒนาการเรียนรู้อย่างยั่งยืนของนักศึกษา ฝึกทักษะในการคิดเชิงบวก ศึกษาการจัดการความรู้และกระบวนการการเรียนรู้ ผ่านการทำโครงงานที่นักศึกษาสนใจ ที่เน้นการกำหนดเป้าหมายทางการเรียนรู้ รู้จักการตั้งโจทย์ การศึกษาวิธีการแสวงหาความรู้ การแยกแยะข้อมูลกับข้อเท็จจริง การอ่าน แก้ปัญหาการสร้างความคิด การคิดอย่างสร้างสรรค์ การคิดเชิงขวาง การสร้างแบบจำลอง การตัดสินใจ การประเมินผลและการนำเสนอผลงาน', 'This course aims to equip students with the skills necessary for life-long learning. Students will learn how to generate positive thinking, manage knowledge and be familiar with learning processes through projects based on their interest. These include setting up learning targets; defining the problems; searching for information; distinguishing between data and fact; generating ideas, thinking creatively and laterally; modeling; evaluating; and presenting the project.', true, now(), now()),
  ('GEN231', 'มหัศจรรย์แห่งความคิด', 'Miracle of Thinking', 3, 'วิชานี้จะให้ความหมาย หลักการ คุณค่า แนวคิด ที่มาและธรรมชาติของการคิด โดยการสอนและพัฒนานักศึกษาให้มีการคิดเป็นระบบ การคิดเชิงระบบ การคิดเชิงวิพากษ์ และการคิดเชิงวิเคราะห์ การอธิบายทฤษฎีหมวก 6 ใบที่เกี่ยวข้องกับการคิด นอกจากนี้ยังได้กล่าวถึงการเชื่อมโยงความคิด/การผูกเรื่อง การเขียนโดยมีการทำตัวอย่างหรือกรณีเพื่อศึกษาการแก้ปัญหาโดยวิธีการคิดเชิงระบบ ด้านวิทยาศาสตร์และเทคโนโลยีสังคม บริหารจัดการ สิ่งแวดล้อมและอื่นๆ', 'This course aims to define the description, principle, value, concept and nature of thinking to enable developing students to acquire the skills of systematic thinking, systems thinking, critical thinking and analytical thinking. The Six Thinking Hats concept is included. Moreover, idea connection/story line and writing are explored. Examples or case studies are used for problem solving through systematic thinking using the knowledge of science and technology, social science, management, and environment, etc.', true, now(), now()),
  ('GEN241', 'ความงดงามแห่งชีวิต', 'Beauty of Life', 3, 'ศึกษาเกี่ยวกับความสัมพันธ์ระหว่างมนุษย์กับคุณค่าและความงามท่ามกลางความหลากหลายทางวัฒนธรรม เน้นที่การรับรู้คุณค่า การสัมผัสความงามและการแสดงออกทางอารมณ์ของมนุษย์ รับรู้และเรียนรู้เกี่ยวกับคุณค่าและความงามในด้านต่างๆ ที่เกี่ยวกับการดำรงชีวิตมนุษย์ เช่น ชีวิตกับความงามในด้านศิลปะ ดนตรี วรรณกรรม รวมไปถึงความงามในธรรมชาติรอบๆ ตัวมนุษย์', 'This course aims to promote the understanding of the relationship between humans and aesthetics amidst the diversity of global culture. It is concerned with the perception, appreciation and expression of humans on aesthetics and value. Students are able to experience learning that stimulates an understanding of the beauty of life, artwork, music and literature, as well as the cultural and natural environments.', true, now(), now()),
  ('GEN351', 'การบริหารจัดการยุคใหม่และภาวะผู้นำ', 'Modern Management and Leadership', 3, 'แนวคิดการบริหารจัดการยุคใหม่ หน้าที่พื้นฐานของการจัดการประกอบด้วย การวางแผน การจัดองค์กร การควบคุม การตัดสินใจ การสื่อสาร การจูงใจ ภาวะผู้นำ การจัดการทรัพยากรมนุษย์การจัดการระบบสารสนเทศ ความรับผิดชอบต่อสังคม ตลอดจนการประยุกต์ใช้สถานการณ์ต่างๆ', 'This course examines the modern management concept including basic functions of management planning, organizing, controlling, decision-making, communication, motivation, leadership, human resource management, management of information systems, social responsibility and its application to particular circumstances.', true, now(), now()),
  ('INT100', 'การคิดเชิงออกแบบ', 'Design Thinking', 1, 'แนวคิดของการคิดเชิงออกแบบ ฝึกปฏิบัติเทคนิคในการ เข้าใจ นิยาม สร้างสรรค์ จำลอง และ ทดลอง', 'Design thinking concepts, practice techniques in emapathize, define, ideate, prototype and test.', true, now(), now()),
  ('INT101', 'คณิตศาสตร์ดิสครีต', 'Discrete Mathematics', 3, 'ตรรกศาสตร์เชิงประพจน์ ตรรกศาสตร์ภาคแสดง ตัวเชื่อมตรรกะ ตารางความจริง ความสมมูลเชิงตรรกะ สัจนิรันดร์ เทคนิคการพิสูจน์ หลักการของพีชคณิตแบบบูลและฟังก์ชันแบบบูล เซตและการดำเนินการกับเซต เซตกำลังและผลคูณคาร์ทีเซียน ฟังก์ชันและความสัมพันธ์ ฟังก์ชันหนึ่งต่อหนึ่ง ฟังก์ชันทั่วถึง ฟังก์ชันหนึ่งต่อหนึ่งทั่วถึง ฟังก์ชันประกอบ ฟังก์ชันผกผัน หลักพื้นฐานของคณิตศาสตร์เชิงการจัด การเรียงสับเปลี่ยนการจัดหมู่ ฟังก์ชันก่อกำเนิด ความสัมพันธ์เวียนเกิด หลักของการเพิ่มเข้า-ตัดออก ลำดับและอนุกรม อุปนัยเชิงคณิตศาสตร์ กราฟและต้นไม้ เครื่องสถานะจำกัดและนิพจน์ปกติ', 'Propositional logic, predicate logic, logical connectives, truth tables, logical equivalence, tautologies, proof techniques, principles of boolean algebra and boolean functions, sets and set operations, power sets and cartesian products, functions and relations, one-to-one function, onto function, and bijective function, composite function, inverse function, basic principles of combinatorial mathematics, permutations, combinations, generating functions, recurrence relations, principle of inclusion-exclusion, sequences and series, mathematical induction, graphs and trees, finite state machine and regular expression', true, now(), now()),
  ('INT102', 'สถิติสำหรับเทคโนโลยีสารสนเทศ', 'Statistics for Information Technology', 2, 'ความรู้เบื้องต้นเกี่ยวกับสถิติ ความสำคัญของสถิติในเทคโนโลยีสารสนเทศ การวัดแนวโน้มสู่ส่วนกลางการวัดการกระจาย เทคนิคการเลือกตัวอย่าง แนวคิดความน่าจะเป็นเบื้องต้น ความน่าจะเป็นมีเงื่อนไข ทฤษฎีบทของเบส์ การแจกแจงทวินาม การแจกแจงปัวซง การแจกแจงปรกติ การใช้เครื่องมือทางสถิติ', 'Introduction to statistics, importance of statistics in information technology, measures of central tendency, measures of variability, sampling techniques, basic probability concepts, conditional probability, Bayes'' theorem, binomial distribution, Poisson distribution, normal distribution, use of statistical tools', true, now(), now()),
  ('INT105', 'สัมมนาเทคโนโลยีสารสนเทศ', 'Information Technology Seminar', 1, 'วิชานี้เป็นแพลตฟอร์มให้นักศึกษาสำรวจและอภิปรายเรื่องที่ทันสมัย เทรนด์ และความก้าวหน้าในสายงานเทคโนโลยีสารสนเทศ ผ่านการนำเสนอ การอภิปราย และการวิเคราะห์อย่างวิจารณ์ นักศึกษาจะมีส่วนร่วมกับหัวข้อต่าง ๆ ตั้งแต่เทคโนโลยีใหม่, ความมั่นคงปลอดภัยของข้อมูล, การวิเคราะห์ข้อมูล, ปัญญาประดิษฐ์, จนถึงผลกระทบทางจริยธรรมและสังคมจากเทคโนโลยีสารสนเทศ การสัมมนาส่งเสริมทักษะการเรียนรู้ด้วยตนเอง ช่วยให้นักศึกษาทันสมัยกับแนวโน้มและการเปลี่ยนแปลงที่เกิดขึ้นในภาพรวมของเทคโนโลยีสารสนเทศ', 'This course provides a platform for students to explore and discuss contemporary issues, trends, and advancements in the field of Information Technology. Through presentations, discussions, and critical analysis, students engage with topics ranging from emerging technologies, cybersecurity, data analytics, artificial intelligence, to ethical and social implications of IT. The seminar fosters self-directed learning skills, enabling students to stay updated with the dynamic landscape of Information Technology.', true, now(), now()),
  ('INT110', 'การคิดเชิงธุรกิจ', 'Business Thinking', 1, 'สาระสำคัญของกรอบความคิดทางธุรกิจและการเป็นผู้ประกอบการ แนวคิดทางธุรกิจส่งผลต่อความสำเร็จส่วนบุคคลและองค์กรอย่างไร ความรู้เบื้องต้นเรื่องการวิเคราะห์ SWOT ความรู้เบื้องต้นเรื่องการคิดและการวางแผนเชิงกลยุทธ์ ความรู้เบื้องต้นเรื่องโมเดลในการตัดสินใจ', 'The essence of a business mindset and entrepreneurship; How a business mindset contributes to personal and organizational success; Basic introduction to SWOT analysis, strategic thinking and planning, and decision-making models', true, now(), now()),
  ('INT111', 'ระบบสารสนเทศเพื่อธุรกิจ', 'Business Information Systems', 3, 'ภาพรวมของฟังก์ชันในธุรกิจที่สำคัญ (การตลาด การเงิน การดำเนินงาน ทรัพยากรบุคคล) หน้าที่ต่างๆ มีส่วนช่วยให้ธุรกิจโดยรวมประสบความสำเร็จได้อย่างไร การวิเคราะห์ปัจจัยภายนอกที่ส่งผลกระทบต่อธุรกิจ (เศรษฐกิจ กฎหมาย เทคโนโลยี สังคม สิ่งแวดล้อม) ความรู้เบื้องต้นเกี่ยวกับหน้าที่และบทบาทของการจัดการ หลักการพื้นฐานของการตลาดและส่วนประสมการตลาด (ผลิตภัณฑ์ ราคา สถานที่ การส่งเสริมการขาย) แนวคิดเรื่องการจัดทำงบประมาณ การวิเคราะห์ทางการเงิน และการจัดการการเงินทางธุรกิจ การจัดการกระบวนการผลิต การควบคุมคุณภาพ และการจัดการห่วงโซ่อุปทาน หน้าที่ด้านทรัพยากรบุคคล การสรรหาบุคลากร การฝึกอบรม การประเมินผลการปฏิบัติงาน และความสัมพันธ์กับพนักงาน การสร้างแบบจำลองและการวิเคราะห์กระบวนการทางธุรกิจ การวิเคราะห์ความท้าทายทางธุรกิจ การใช้ระบบสารสนเทศเพื่อสนับสนุนการดำเนินงานและการตัดสินใจ', 'Overview of key business functions (marketing, finance, operations, human resources); How different functions contribute to overall business success; Analysis of external factors affecting business (economic, legal, technological, social, environmental); Introduction to management functions and roles; Basic principles of marketing and the marketing mix (product, price, place, promotion); Concepts of budgeting, financial analysis, and managing business finances; Managing production processes, quality control, and supply chain management; HR functions, recruitment, training, performance evaluation, and employee relations; Business process modeling and analysis; Analyzing business challenges; Using information system to support operations and decision-making', true, now(), now()),
  ('INT115', 'การปฏิบัติอย่างนักเทคโนโลยีสารสนเทศมืออาชีพ', 'Information Technology Professional Practices', 2, 'ข้อพิจารณาทางจริยธรรมและความรับผิดชอบของผู้เชี่ยวชาญด้านไอที จรรยาบรรณในอุตสาหกรรมไอที ทักษะการสื่อสารที่มีประสิทธิภาพสำหรับผู้เชี่ยวชาญด้านไอที การสื่อสารอย่างสันติ การเขียนเอกสารทางเทคนิค อีเมล และรายงาน ชุดทักษะที่จำเป็นในการทำงานอย่างมีประสิทธิภาพในสภาพแวดล้อมของทีมเครื่องมือและแนวปฏิบัติในการทำงานร่วมกันสำหรับทีมระยะไกลและแบบกระจาย บทบาทของการกำกับดูแลด้านไอทีในการปรับไอทีให้สอดคล้องกับเป้าหมายทางธุรกิจ กลยุทธ์เพื่อความก้าวหน้าในอาชีพและการเติบโตทางอาชีพ องค์ประกอบของเรซูเม่ทางเทคนิคที่ประสบความสำเร็จ', 'Ethical considerations and responsibilities of IT professionals; Codes of ethics in the IT industry; Effective communication skills for IT professionals, nonviolent communication; Writing technical documentation, emails, and reports; Skill sets needed to function effectively in a team environment; Collaboration tools and practices for remote and distributed teams; Role of IT governance in aligning IT with business goals; Strategies for career advancement and professional growth; The elements of a successful technical resume', true, now(), now()),
  ('INT116', 'ประเด็นทางกฎหมายและจริยธรรมในเทคโนโลยีสารสนเทศ', 'Legal and Ethical Issues in Information Technology', 1, 'ภาพรวมของหลักการทางกฎหมายและความเกี่ยวข้องในบริบทของเทคโนโลยีสารสนเทศ ทำความเข้าใจความเกี่ยวข้องของเทคโนโลยี กฎหมาย และจริยธรรม กฎหมายที่เกี่ยวข้องกับลิขสิทธิ์ สิทธิบัตรเครื่องหมายการค้า และความลับทางการค้า และการนำมาใช้กับซอฟต์แวร์ เนื้อหาดิจิทัล และสิ่งประดิษฐ์ การใช้งานโดยชอบธรรม สาธารณสมบัติ และข้อตกลงสิทธิ์การใช้งาน; ความสำคัญของการปกป้องข้อมูลที่ละเอียดอ่อนและความเป็นส่วนตัวของผู้ใช้ ภาพรวมของประเด็นทางกฎหมายที่เกี่ยวข้องกับสัญญาด้านไอทีความรับผิด และข้อพิพาทด้านทรัพย์สินทางปัญญา ผลกระทบทางกฎหมายของการแฮก การละเมิดลิขสิทธิ์และอาชญากรรมไซเบอร์อื่น ๆ', 'Overview of legal principles and their relevance in the context of information technology; Understanding the intersection of technology, law, and ethics; Copyright, patent, trademark, and trade secret laws and their application to software, digital content, and inventions; Fair use, public domain, and licensing agreements; Importance of safeguarding sensitive data and user privacy; Overview of legal issues related to IT contracts, liabilities, and intellectual property disputes; The legal ramifications of hacking, piracy, and other cybercrimes.', true, now(), now()),
  ('INT120', 'พื้นฐานการออกแบบประสบการณ์ของผู้ใช้และส่วนต่อประสาน', 'UX/UI Design Fundamentals', 3, 'ความรู้พื้นฐานเกี่ยวกับการออกแบบประสบการณ์ที่มีผู้ใช้เป็นศูนย์กลาง กระบวนการและเทคนิคที่ใช้ในการออกแบบประสบการณ์ผู้ใช้งาน เครื่องมือในการออกแบบ เช่น Personas หรือ User Journey Maps ปัจจัยด้านมนุษย์ จิตวิทยาการรับรู้ มาตรฐานด้านความใช้งานได้ มาตรฐานการเข้าถึงได้ และความรู้เบื้องต้นในการออกแบบส่วนติดต่อกับผู้ใช้งาน', 'Fundamental knowledge about designing user-centered experiences; the processes and techniques in user experience design; Design tools, such as Personas or User Journey Maps; Human factors, cognitive psychology, usability standards, accessibility standards; Basic knowledge of designing user interface components', true, now(), now()),
  ('INT130', 'พื้นฐานแพลตฟอร์มคอมพิวเตอร์', 'Computing Platform Basics', 1, 'แนะนำแพลตฟอร์มคอมพิวเตอร์ การแทนข้อมูลพื้นฐานในคอมพิวเตอร์ ภาพรวมส่วนประกอบของฮาร์ดแวร์ ภาพรวมระบบปฏิบัติการ พื้นฐานระบบแฟ้มข้อมูล พื้นฐานการทำงานแบบเสมือน การประมวลผลและบริการบนคลาวด์ การติดตั้งและตั้งค่าระบบปฏิบัติการตั้งโต๊ะ บริการไอที เช่น บริการไดเรคทอรี บริการแชร์ไฟล์ และเว็บเซิร์ฟเวอร์', 'Introduction to computing platform, basic data representation, hardware components overview, operating system overview, file system basic, virtualization basic, cloud computing and services, desktop OS installation and setup, IT services such as directory service, file sharing service, and web server', true, now(), now()),
  ('INT131', 'หลักการแพลตฟอร์มคอมพิวเตอร์', 'Computing Platform Principles', 1, 'หลักเบื้องต้นของสถาปัตยกรรมคอมพิวเตอร์และส่วนประกอบของฮาร์ดแวร์ วงจรการดึง-แปล-รันของซีพียู ลำดับขั้นของหน่วยความจำ ส่วนต่อประสานของอินพุทเอาท์พุท หลักการของระบบปฏิบัติการ การทำงานพร้อมกันและเงื่อนไขการแข่งขัน หน่วยความจำเสมือน', 'Fundamentals of computing architecture and hardware components, fetch-decode- execute cycle, memory hierarchy, I/O interface, operating system principles, concurrency and race conditions, virtual memory', true, now(), now()),
  ('INT132', 'พื้นฐานลินุกซ์และการเขียนเชลล์สคริปต์', 'Linux Fundamentals and Shell Scripting', 1, 'คำสั่งพื้นฐานของ Linux เช่น คำสั่งจัดการไฟล์และไดเรกทอรี การเปลี่ยนทิศทางของข้อมูล รวมถึงการเขียนเชลล์สคริปต์พื้นฐาน', 'Basic Linux commands such as file systems operations and redirections, including basic shell scripting.', true, now(), now()),
  ('INT133', 'เครือข่ายคอมพิวเตอร์', 'Computer Networks', 3, 'ภาพรวมของ ชุดโพรโทคอลทีซีพีไอพี และ บริการต่าง ๆ แอปพลิเคชันและโพรโทคอลที่ทำงานในอินเทอร์เน็ต เช่น เว็บ อีเมล การทำงานของโพรโทคอลทางเครือข่าย เช่น ทีซีพี ยูดีพี ทีแอลเอส โดเมนเนมพอร์ต และเลขที่อยู่ไอพี หน้าที่ของอุปกรณ์เครือข่าย ระบบแลนแบบอีเทอร์เน็ตและแบบไร้สาย สายสัญญาณบริการทางเครือข่าย เช่น ดีเอ็นเอส ดีเอชซีพี พร็อกซี และ วีพีเอ็น', 'Overview of TCP/IP suite layers and services, Internet applications and protocols such as web, email; operations of network protocols such as TCP, UDP, TLS, IP, domain name, port and IP address; network equipment and their functions; Ethernet LAN and Wireless LAN, cables, network services such as DNS, DHCP, Proxy, and VPN.', true, now(), now()),
  ('INT134', 'การติดตั้งระบบ', 'System Deployment', 2, 'การติดตั้งเว็บแอปพลิเคชันบนเครื่องเสมือนที่ใช้ระบบปฏิบัติการลินุกซ์ การติดตั้งเซิร์ฟเวอร์ซอฟต์แวร์, การตั้งค่าเซิร์ฟเวอร์ซอฟต์แวร์, การบิวท์เว็บแอปพลิเคชันด้วยตัวจัดการแพคเกจ เทคโนโลยีการทำคอนเทนเนอร์ และการแก้ปัญหา', 'Deployment of web application on Linux virtual machine. Installation of server software, server configuration, building web application using package manager, container technology, and trouble-shooting.', true, now(), now()),
  ('INT135', 'ความมั่นคงขั้นพื้นฐาน', 'Basic Security', 1, 'การรักษาความมั่นคงที่ใช้งานได้จริง การลดความเสี่ยงและการกู้คืน ประเด็นในการปฏิบัติด้านความมั่นคง การรายงานข้อมูลด้านความมั่นคง ความมั่นคงสำหรับระบบคลาวด์ ความมั่นคงของบุคลากรและบุคคลมิติทางสังคม', 'Usable security, mitigation and recovery, operational issues, reporting requirements, cloud security, personnel and human security, social dimensions', true, now(), now()),
  ('INT136', 'ความมั่นคงทางไซเบอร์', 'Cyber Security', 2, 'บริการด้านความมั่นคง กลไกและมาตรการตอบโต้การบุกรุก คุณสมบัติด้านความมั่นคง ลักษณะการบุกรุกและวิธีตรวจสอบ จุดอ่อน การคุกคามและความเสี่ยง จุดอ่อนของระบบเว็บและโมบาย', 'Security services, mechanisms and countermeasures; security properties; cyber-attacks and detection; vulnerabilities, threats and risks; web and mobile vulnerabilities', true, now(), now()),
  ('INT140', 'การคิดเชิงคอมพิวเตอร์', 'Computational Thinking', 3, 'แนวคิดพื้นฐานที่จำเป็นสำหรับใช้แก้ไขปัญหาเชิงคอมพิวเตอร์ ได้แก่ การแยกองค์ประกอบของปัญหาการรู้จำแบบ การกำหนดสาระสำคัญ และการคิดเชิงอัลกอริทึม', 'Fundamental concepts needed for solving computational problems: decomposition, pattern recognition, abstraction, and algorithmic thinking.', true, now(), now()),
  ('INT141', 'การเขียนโปรแกรมเบื้องต้น', 'Basic Programming', 3, 'แนวคิดพื้นฐานการเขียนโปรแกรม ชนิดข้อมูล นิพจน์ คำสั่งพื้นฐาน โครงสร้างควบคุม อารเรย์ อ็อบเจ็กต์ ฟังก์ชัน', 'Basic Programming Concepts, Data Types, Expressions, Statements, Control Structures, Array, Objects, Functions', true, now(), now()),
  ('INT142', 'เครื่องมือการพัฒนาซอฟต์แวร์', 'Software Development Tools', 1, 'สภาพแวดล้อมสำหรับการพัฒนาแบบเบ็ดเสร็จ (IDE) ยอดนิยม การสร้างโปรเจกต์ การเขียนโค้ด และการดีบัก การใช้เครื่องมือสร้างอัตโนมัติในการคอมไฟล์และแพ็กเกจซอฟต์แวร์ ความรู้เบื้องต้นเกี่ยวกับระบบควบคุมเวอร์ชัน การใช้เครื่องมือเช่น GitHub สำหรับการทำงานร่วมกันของโค้ดและการรีวิวโดยเพื่อนร่วมงานการแนะนำการใช้เครื่องมือการจัดการโครงการ', 'Popular Integrated Development Environments (IDEs); Setting up projects, writing code, and using debugging features; Using build automation tools to streamline compilation and packaging; Introduction to version control systems; Utilizing tools like GitHub for code collaboration and peer review; Introduction to project management tools', true, now(), now()),
  ('INT143', 'พื้นฐานกระบวนการพัฒนาซอฟต์แวร์', 'Software Process Fundamentals', 1, 'เป้าหมายของการพัฒนาซอฟต์แวร์ กิจกรรมในการพัฒนาซอฟต์แวร์ วรจรชีวิตแบบน้ำตก การพัฒนาแบบวนซ้ำและต่อเติม', 'The goal of software development; Software development activities; Waterfall life- cycle model; Introduction to iterative and incremental development', true, now(), now()),
  ('INT144', 'การพัฒนาซอฟต์แวร์แบบอไจล์ 1', 'Agile Software Development I', 1, 'ภาพรวมของหลักการอไจล์และคำแถลงอุดมการณ์อไจล์ การเปรียบเทียบระหว่างวิธีการพัฒนาซอฟต์แวร์แบบอไจล์และแบบเดิม บทบาทและความรับผิดชอบในสกรัม (สกรัมมาสเตอร์ เจ้าของผลิตภัณฑ์ทีมพัฒนา) การประชุมรายวันแบบ Stand-up', 'Overview of Agile principles and the Agile Manifesto; Comparison between Agile and traditional software development methodologies; Understanding roles and responsibilities (Scrum Master, Product Owner, Development Team); Daily stand-up', true, now(), now()),
  ('INT145', 'การวิเคราะห์และออกแบบซอฟต์แวร์', 'Software Analysis and Design', 2, 'เทคนิคในการรวบรวมความต้องการของผู้ใช้และดึงเอาความต้องการของระบบ การระบุผู้มีส่วนได้ส่วนเสีย การสัมภาษณ์ การสำรวจ และการสร้างแบบจำลองกรณีการใช้งาน ภาพรวม UML (Unified', 'Modeling Language) และบทบาทในการสร้างแบบจำลองระบบ แผนภาพกรณีใช้งาน แผนภาพกิจกรรม และแผนภาพลำดับ แนวคิดของหลักการวิเคราะห์เชิงวัตถุและการออกแบบ การออกแบบสถาปัตยกรรมระบบ ส่วนประกอบ และโมดูล แบบจำลองสี่ซี Techniques for gathering user needs and eliciting system requirements; Stakeholder identification, interviews, surveys, and use case modeling; UML (Unified Modeling Language) overview and its role in system modeling; Use case diagrams, activity diagrams, and sequence diagrams; Concepts of object-oriented analysis and design principles; Designing system architecture, components, and modules; C4 model', true, now(), now()),
  ('INT146', 'การทดสอบซอฟต์แวร์', 'Software Testing', 1, 'ความสำคัญของการทดสอบซอฟต์แวร์ในกระบวนการพัฒนา บทบาทของการทดสอบในการรับรองคุณภาพและความน่าเชื่อถือของซอฟต์แวร์ ระดับการทดสอบต่าง ๆ (หน่วย การบูรณาการ ระบบ การยอมรับ) การสำรวจประเภทการทดสอบ (แบบฟังก์ชัน แบบไม่เป็นฟังก์ชัน การถดถอย ความสามารถในการนำไปใช้งาน) การสร้างแผนการทดสอบโดยสรุปวัตถุประสงค์และขอบเขตการทดสอบ การออกแบบกรณีทดสอบตามความต้องการและสถานการณ์ ดำเนินการกรณีทดสอบและบันทึกผลการทดสอบ การรายงานและจัดลำดับความสำคัญข้อบกพร่องโดยใช้เครื่องมือติดตามจุดบกพร่อง', 'Importance of software testing in the development process; Role of testing in ensuring software quality and reliability; Different levels of testing (unit, integration, system, acceptance); Exploring testing types (functional, non-functional, regression, usability); Creating test plans outlining testing objectives and scope; Designing test cases based on requirements and scenarios; Executing test cases and documenting test results; Reporting and prioritizing defects using bug tracking tools', true, now(), now()),
  ('INT147', 'การพัฒนาซอฟต์แวร์แบบอไจล์ 2', 'Agile Software Development II', 2, 'ค่านิยมของสกรัม หลักการวางแผนแบบสกรัม การวางแผนในระดับผลิตภัณฑ์ การวางแผนในระดับรอบการส่งมอบ การวางแผนในระดับสปรินท์ ยูสเซอร์สตอรี่ งานค้างของผลิตภัณฑ์ การประมาณการและความเร็ว การดำเนินการในสปรินท์ สปรินท์รีวิว การทบทวนสปรินท์ การเขียนโปรแกรมแบบเอ็กส์ตรีม', 'Scrum Values, Scrum Planning Principles, Product Planning, Release Planning, Sprint Planning, User Stories and Product Backlog, Estimation and Velocity, Sprint Execution, Sprint Review, Sprint Retrospective, Extreme Programming (XP)', true, now(), now()),
  ('INT150', 'เทคโนโลยีเว็บ', 'Web Technology', 3, 'ความรู้พื้นฐานเกี่ยวกับเทคโนโลยีเว็บ สถาปัตยกรรมของเว็บ เอชทีทีพี/เอชทีทีพีเอสและสแตติกและไดนามิกเอชทีเอ็มแอล ซีเอสเอส และสื่อประสมบนเว็บ การสร้างเว็บไซต์ การออกแบบหน้าเว็บซีเอสเอสด้วยเฟลคบ็อกและกริด การออกแบบเว็บเรสปอนซีฟ', 'Basic Web Technooogy, Web Architecture, HTTP/HTTPS, static and dynamic HTML, CSS and web multimedia. Web creation, CSS Layout with Flexbox and Grid, Responsive Web Design', true, now(), now()),
  ('INT151', 'การพัฒนาฟรอนเอนด์พื้นฐาน', 'Basic Frontend Development', 3, 'ดอม การจัดการเหตุการณ์ พื้นที่เก็บข้อมูลฝั่งลูกข่าย การเขียนโปรแกรมแบบไม่ประสานเวลา เฟชเอพีไอ', 'DOM, Events, Client-Side Storages, Asynchronous Programming, Fetch API', true, now(), now()),
  ('INT161', 'การพัฒนาแบ็กเอนด์พื้นฐาน', 'Basic Backend Development', 3, 'ความรู้เบื้องต้นเกี่ยวกับ RESTful API การเชื่อมต่อกับฐานข้อมูล API ระบุตัวตน และความปลอดภัยการเรียงลำดับ การแบ่งข้อมูลออกเป็นหน้า และการกรองข้อมูล', 'Basic REST API, Connection with Database, API Authentication and Security, Sorting, Pagination and Filtering', true, now(), now()),
  ('INT180', 'ความสามารถด้านข้อมูล', 'Data Literacy', 1, 'แนวคิดการตัดสินใจด้วยข้อมูล การทำความเข้าใจข้อมูล การทำงานกับข้อมูล การอ่านข้อมูล และการตีความข้อมูล โดยคำนึงถึงหลักจริยธรรมและกฎหมายที่เกี่ยวข้องกับข้อมูล', 'Data-driven decision making concepts, understanding data, working with data, reading data and interpreting data with awareness of ethical dimensions of data, and legal issues surrounding data.', true, now(), now()),
  ('INT182', 'พื้นฐานวิทยาการข้อมูลและปัญญาประดิษฐ์', 'Data Science and Artificial Intelligence Fundamentals', 3, 'ความรู้เบื้องต้นเกี่ยวกับวิทยาการข้อมูล การรวบรวมและการเตรียมข้อมูล การวิเคราะห์ข้อมูลเชิงสำรวจ วิศวกรรมคุณลักษณะ ความรู้เบื้องต้นเกี่ยวกับเครื่องมือเรียนรู้ของเครื่อง การประเมินโมเดลพื้นฐานการวิเคราะห์เชิงทำนาย เครื่องมือวิทยาการข้อมูล การประยุกต์ใช้และผลกระทบของวิทยาการข้อมูลข้อพิจารณาทางจริยธรรมในวิทยาการข้อมูล ความรู้เบื้องต้นเกี่ยวกับปัญญาประดิษฐ์ อัลกอริทึมการค้นหาและการเพิ่มประสิทธิภาพ การแทนความรู้และการใช้เหตุผล ความรู้เบื้องต้นเกี่ยวกับการเรียนรู้เชิงลึก การประยุกต์ใช้ปัญญาประดิษฐ์ในโลกแห่งความเป็นจริง เครื่องมือและแพลตฟอร์มปัญญาประดิษฐ์ ข้อพิจารณาทางจริยธรรมในปัญญาประดิษฐ์ แนวโน้มอนาคตและเทคโนโลยีที่เกิดขึ้นใหม่ในด้านปัญญาประดิษฐ์', 'Introduction to data science, data collection and preprocessing, exploratory data analysis, feature engineering, introduction to machine learning, basic model evaluation, predictive analysis, data science tools, applications and impact of data science, ethical considerations in data science, Introduction to artificial intelligence, search algorithms and optimization, knowledge representation and reasoning, introduction to deep learning, artificial intelligence in real-world applications, artificial intelligence tools and platforms, ethical considerations in artificial intelligence, future trends and emerging technologies in artificial intelligence', true, now(), now()),
  ('INT185', 'การแสดงผลข้อมูลด้วยภาพเบื้องต้น', 'Basic Data Visualization', 1, 'ความรู้เบื้องต้นเกี่ยวกับการจินตทัศน์ข้อมูล การเก็บข้อมูลและการทำความสะอาดข้อมูล แผนภูมิและกราฟ ทฤษฎีสีและหลักการออกแบบในงานด้านจินตทัศน์ข้อมูล การสร้างจินตทัศน์ข้อมูลเชิงโต้ตอบ การเล่าเรื่องผ่านข้อมูล จินตทัศน์ข้อมูลสำหรับการรายงานข้อมูล เครื่องมือสร้างจินตทัศน์ข้อมูล', 'Introduction to data visualization, data gathering and cleansing, charts and graphs, color theory and design principles in data visualization, interactive data visualization, data storytelling, data visualization for data reporting, data visualization tools', true, now(), now()),
  ('INT189', 'การกำกับดูแลข้อมูล', 'Data Governance', 1, 'ความรู้เบื้องต้นเกี่ยวกับการกำกับดูแลข้อมูล หรือ ธรรมาภิบาลข้อมูล กรอบและโครงสร้างการกำกับดูแลข้อมูล กระบวนการกำกับดูแลข้อมูล วงจรชีวิตข้อมูล ผู้มีส่วนได้ส่วนเสียกับข้อมูล ระเบียบ คำสั่งและพระราชบัญญัติที่เกี่ยวข้องกับองค์กรในการกำกับดูแลข้อมูล', 'Introduction to data governance, data governance framework and structures, data governance processes, data life cycle, data stakeholders, rules and regulations related to an organization for data governance', true, now(), now()),
  ('INT190', 'เอสคิวแอลพื้นฐาน', 'Basic SQL', 1, 'การสร้างโครงสร้างฐานข้อมูลอย่างง่าย การเขียนคำสั่งเอสคิวแอลขั้นพื้นฐาน การเขียนนิพจน์ การเรียงลำดับข้อมูล การเรียกดูข้อมูล การคัดเลือกข้อมูลโดยการใช้การดำเนินการด้านการคำนวณทางคณิตศาสตร์ ด้านการเปรียบเทียบ และด้านตรรกศาสตร์ การใช้ฟังก์ชันพื้นฐานและฟังก์ชันการรวมกลุ่มข้อมูลการดำเนินการของเซต การเรียกดูข้อมูลจากหลายตาราง และการเปลี่ยนแปลงข้อมูล', 'Creating simple database structures. Writing basic Structured Query Language (SQL) statements, expressions, sorting, selecting data using arithmetic operations, comparison operations and logic operations, using basic functions and aggregate functions, set operations, displaying data from multiple tables and writing SQL statements to manipulate data.', true, now(), now()),
  ('INT191', 'แนวคิดและการออกแบบฐานข้อมูลเชิงสัมพันธ์', 'Relational Database Concepts and Design', 2, 'ความรู้เบื้องต้นเกี่ยวกับฐานข้อมูล แนวคิดของฐานข้อมูลเชิงสัมพันธ์ สถาปัตยกรรมฐานข้อมูลสภาพแวดล้อมฐานข้อมูล การออกแบบฐานข้อมูลด้วยแบบจำลองความสัมพันธ์ของข้อมูล การใช้เครื่องมือในการสร้างแบบจำลองความสัมพันธ์ของข้อมูล และกระบวนการนอร์มอลไลซ์', 'Introduction to databases, relational database concept, database architecture, database environment, database design using entity-relationship model, using tools for creating an entity-relationship model and normalization.', true, now(), now()),
  ('INT220', 'การออกแบบประสบการณ์ของผู้ใช้', 'UX Design', 3, 'การสร้างประสบการณ์ส่วนบุคคล อารมณ์ และความประทับใจในเชิงบวก วิธีการเข้าใจผู้ใช้ กลยุทธ์การออกแบบเชิงพื้นที่และเชิงพฤติกรรม จิตวิทยาของปฏิสัมพันธ์ของมนุษย์ กระบวนการของประสบการณ์ผู้ใช้ วิธีวิจัยผู้ใช้ เครื่องมือและเทคนิค และการออกแบบปฏิสัมพันธ์', 'Creating a positive personal experience, emotion, and impressions; Understanding the user; Spatial and behavioral strategies; Psychology of human interaction, UX process, user research methodology, tools and technique, design strategy and interaction design', true, now(), now()),
  ('INT221', 'การออกแบบส่วนต่อประสาน', 'UI Design', 3, 'ความรู้เบื้องต้นเกี่ยวกับองค์ประกอบการออกแบบ องค์ประกอบของภาพ เช่น ตัวหนังสือ สี ข้อความย่อย ภาพและเค้าโครง นิยามขององค์ประกอบ กายภาพ และสถานะของส่วนประกอบของ UI การจัดระเบียบและการแสดงภาพข้อมูล ส่วนประกอบการนำทาง ส่วนประกอบโครงสร้างเพจ และ แนวทางปฏิบัติที่ดีที่สุดสำหรับการออกแบบ UI เช่น หน้า Landing Page การเข้าสู่ระบบ การลงทะเบียน และแบบฟอร์มอื่น ๆ', 'Introduction to design composition; Visual elements such as typography, color, microcopy, imagery, and layouts; Component definitions, anatomy, and states of the UI components; Organizing and visualizing data, navigational components, page structure components; Best practices for UI designing such as a landing page, logins, signups, and other forms', true, now(), now()),
  ('INT222', 'การวัดและวิเคราะห์ประสบการณ์ของผู้ใช้และส่วนต่อประสาน', 'UX/UI Measurement and Analysis', 3, 'แนวคิดและเทคนิคที่ใช้ในการประเมิน การวิเคราะห์ และการวัดผลประสบการณ์ของผู้ใช้และส่วนต่อประสาน เครื่องมือและซอฟต์แวร์สำหรับเก็บข้อมูลพฤติกรรมการใช้งาน การวิเคราะห์ และการประเมินผลการใช้งาน', 'Techniques and concept to evaluate, analyze, and measure user experience and user interface; software and tools to collect, analyze and evaluate user behavior data.', true, now(), now()),
  ('INT240', 'แนวคิดการเขียนโปรแกรมขั้นสูง', 'Advanced Programming Concepts', 3, 'ความรู้เบื้องต้นเกี่ยวกับกระบวนทัศน์การเขียนโปรแกรมแบบต่าง ๆ เช่น การเขียนโปรแกรมเชิงวัตถุการเขียนโปรแกรมเชิงฟังก์ชัน, แนวคิดเกี่ยวกับการเขียนโปรแกรมเพื่องานในลักษณะต่าง ๆ เช่น การเขียนโปรแกรมที่มีภาวะการเกิดพร้อมกัน', 'Introduction to different programming paradigms, e.g., object-oriented programming, functional programming. Programming concepts for different computational tasks, e.g., concurrency.', true, now(), now()),
  ('INT241', 'โครงสร้างข้อมูลและอัลกอริทึม', 'Data Structures and Algorithms', 3, 'ความรู้พื้นฐานเกี่ยวกับโครงสร้างข้อมูลและอัลกอริทึมสำหรับการเรียงลำดับ การค้นหา และการปรับปรุงแก้ไขข้อมูล ความรู้พื้นฐานทางคณิตศาสตร์สำหรับวิเคราะห์ความซับซ้อนของอัลกอริทึม เพื่อให้ผู้เรียนสามารถเลือกและประยุกต์ใช้โครงสร้างข้อมูลและอัลกอริทึมอย่างเหมาะสมกับปัญหาเชิงคอมพิวเตอร์', 'Fundamentals of data structures and algorithms for sorting, searching, and modification of data. Mathematical foundation for analysis of algorithmic complexity. Applications of data structures and algorithms to solve computational problems.', true, now(), now()),
  ('INT242', 'การเขียนโปรแกรมจาวา', 'Java Programming', 3, 'ความรู้เบื้องต้นเกี่ยวกับการเขียนโปรแกรมภาษาจาวา, โมเดลการดำเนินการของจาวา, คำสั่งพื้นฐานของภาษาจาวา, การเขียนโปรแกรมเชิงวัตถุด้วยภาษาจาวา, อาร์เรย์, การจัดการข้อผิดพลาดของภาษาจาวา, อินพุต เอาท์พุต, Generics และ Collections, การเชื่อมต่อฐานข้อมูลด้วย JDBC, เธรด', 'Introduction to Java programming, Java execution model, Java Language Basics, Object- oriented programming with the Java programming language, Arrays, Exceptions, Java I/O, Generics and Collections, JDBC, Threads.', true, now(), now()),
  ('INT243', 'การเขียนโปรแกรมไพทอน', 'Python Programming', 3, 'ความรู้เบื้องต้นเกี่ยวกับการเขียนโปรแกรมภาษาไพทอน ไวยากรณ์ของภาษาไพทอน ชนิดข้อมูลพื้นฐาน ลิสต์ ทูเพิล เซต ดิกชันนารี การดำเนินการรับเข้าและส่งออก โครงสร้างควบคุม ฟังก์ชัน พารามิเตอร์ของฟังก์ชันและค่าส่งกลับ ฟังก์ชันแลมบ์ดา โมดูลและแพ็กเกจ การจัดการไฟล์ การเชื่อมต่อกับแหล่งข้อมูลต่าง ๆ การดำเนินการกับสตริงและนิพจน์ปกติ ไลบรารีที่จำเป็นสำหรับปัญญาประดิษฐ์และวิทยาการข้อมูลการประยุกต์ใช้การเขียนโปรแกรมภาษาไพทอนกับปัญหาจริง', 'Introduction to python programming, python syntax, basic data types, lists, tuples, sets, dictionaries, input and output operations, control statements, functions, function parameters and return values, lambda functions, modules and packages, file handling, connecting to various data sources, string operations and regular expressions, essential libraries for artificial intelligence and data science, applying python programming to real-world problems.', true, now(), now()),
  ('INT250', 'ซีเอสเอสเฟรมเวิร์ก', 'CSS Framework', 3, 'การติดตั้งและตั้งค่าซีเอสเอสเฟรมเวิร์ก การออกแบบและเบรกพอยต์ที่ตอบสนอง การออกแบบตัวอักษรและข้อความ การทำงานกับสี การวางผัง การเว้นวรรคและระยะขอบ แอนิเมชันและการเปลี่ยน', 'CSS Framework Installation and Setup, Responsive Design and Breakpoints, Typography and Text Styling, Working with Colors, Layouts, Spacing and Margins, Animation and Transition', true, now(), now()),
  ('INT251', 'เฟรมเวิร์กสำหรับการพัฒนาฟรอนเอนด์', 'Frontend Development Framework', 3, 'แนะนำฟรอนเอนด์เฟรมเวิร์ก พื้นฐานการทำรีแอคทีฟ การแสดงผลตามเงื่อนไข การแสดงผลรายการการจัดการเหตุการณ์ การผูกคลาสและสไตล์ ส่วนประกอบข การสื่อสารระหว่างส่วนประกอบ ส่วนประกอบที่ประกอบได้ การกำหนดเส้นทาง การจัดการสถานะ', 'Introduction to Frontend Framework, Reactivity Fundamentals, Conditional Rendering, List Rendering, Event Handling, Class and Style Bindings, Components, Communicating between components, Composable Components, Routing, State Management', true, now(), now()),
  ('INT261', 'เฟรมเวิร์กสำหรับการพัฒนาแบ็กเอนด์', 'Backend Development Framework', 3, 'แนะนำพื้นฐานของการพัฒนาเว็บ, โพรโทคอล HTTP, แนวคิดของ RESTful API, คุณสมบัติหลักของ', 'Spring Boot framework, การสร้าง RESTful APIs ด้วย Spring Boot, การสร้างโปรเจคแบ็คเอนด์และการ นำไปติดตั้งเพื่อใช้งาน, การเชื่อมต่อฐานข้อมูล, การตรวจสอบสิทธิ์และการยืนยันตัวตน, การจัดการ ข้อผิดพลาดและการบันทึกล็อก Introduce to the fundamentals of web development, HTTP, RESTful API concepts, Spring Boot framework and its core features, building RESTful APIs with Spring Boot, build and deploy backend, database integration, authentication and authorization, error handling and logging.', true, now(), now()),
  ('INT270', 'คณิตศาสตร์สำหรับปัญญาประดิษฐ์', 'Mathematics for Artificial Intelligence', 3, 'พีชคณิตเชิงเส้น เวกเตอร์และการดำเนินการบนเวกเตอร์ เมตริกซ์และการดำเนินการบนเมตริกซ์ระบบสมการเชิงเส้น ค่าลักษณะเฉพาะและเวกเตอร์ลักษณะเฉพาะ การแยกค่าเอกฐาน การโปรแกรมในพีชคณิตเชิงเส้น การประยุกต์ใช้พีชคณิตเชิงเส้นในวิทยาการข้อมูลและปัญญาประดิษฐ์ แคลคูลัส ลิมิตและความต่อเนื่อง อนุพันธ์และกฎการอนุพันธ์ ปัญหาการหาค่าเหมาะสมที่สุด การหาค่าเหมาะสุดแบบมีข้อจำกัดปริพันธ์ การเขียนโปรแกรมในแคลคูลัส การประยุกต์ใช้แคลคูลัสในวิทยาการ์ข้อมูลและปัญญาประดิษฐ์', 'Linear algebra: vectors and vector operations, matrices and matrix operations systems of linear equations, eigenvalues and eigenvectors, singular value decomposition, programming in linear algebra, applications of linear algebra in data science and artificial intelligence, calculus: limits and continuity, derivatives and differentiation rules, optimization problems, constrained optimization, integrals, programming in calculus, applications of calculus in data science and artificial intelligence', true, now(), now()),
  ('INT271', 'การเรียนรู้ของเครื่อง', 'Machine Learning', 3, 'การเรียนรู้แบบมีผู้สอน เวิร์กโฟลว์การเรียนรู้แบบมีผู้สอน เคเนียร์เรสเนเบอร์ ต้นไม้ตัดสินใจ ซัพพอร์ตเวคเตอร์แมชชีน การถดถอยโลจีสติก การถดถอย การประเมินโมเดลการเรียนรู้แบบมีผู้สอน การเรียนรู้แบบไม่มีผู้สอน เวิร์กโฟลว์การเรียนรู้แบบไม่มีผู้สอน การแบ่งกลุ่มข้อมูลแบบเคมีน การแบ่งกลุ่มตามความหนาแน่น การประเมินโมเดลการเรียนรู้แบบไม่มีผู้สอน การเรียนรู้แบบเสริมกำลัง เวิร์กโฟลว์การเรียนรู้แบบเสริมกำลัง กระบวนการตัดสินใจแบบมาร์คอฟ ขั้นตอนวิธีเรียนรู้แบบคิว การประเมินโมเดลการเรียนรู้แบบเสริมกำลัง การประยุกต์ใช้การเรียนรู้ของเครื่องในวิทยาศาสตร์ข้อมูลและปัญญาประดิษฐ์', 'Supervised learning: supervised learning workflows, k-nearest neighbors, decision tree, support vector machine, logistic regression, regression, supervised learning model evaluation, unsupervised learning: unsupervised learning workflows, k-means clustering, hierarchical clustering, density-based clustering, unsupervised learning model evaluation, reinforcement learning: reinforcement learning workflows, Markov decision processes, Q-learning algorithm, reinforcement learning model evaluation, application of machine learning in data science and artificial intelligence', true, now(), now()),
  ('INT272', 'เครือข่ายประสาทประดิษฐ์และการเรียนรู้เชิงลึก', 'Artificial Neural Networks and Deep Learning', 2, 'ความรู้เบื้องต้นเกี่ยวกับเครือข่ายประสาทประดิษฐ์ เครือข่ายประสาทเชิงลึก การหาค่าเหมาะที่สุดและเรกูลาร์ไรเซชันสำหรับการเรียนรู้เชิงลึก เครือข่ายประสาทคอนโวลูชัน สถาปัตยกรรมซีเอ็นเอ็นขั้นสูง การเรียนรู้แบบถ่ายโอน เครือข่ายประสาทแบบวนกลับ การเรียนรู้แบบเสริมแรงเชิงลึก', 'Introduction to Artificial Neural Networks, Deep Neural Networks, Optimization and Regularization for Deep Learning, Convolutional Neural Networks (CNNs), Advanced CNN Architectures, Transfer Learning, Recurrent Neural Networks (RNNs), Deep Reinforcement Learning', true, now(), now()),
  ('INT273', 'การเรียนรู้เชิงลึกแบบก่อกำเนิด', 'Generative Deep Learning', 1, 'กลไกการให้ความสนใจ ตัวแปลง ตัวแปลงก่อกำเนิดแบบฝึกสอนล่วงหน้า ตัวเข้ารหัสอัตโนมัติและการประยุกต์ใช้ ตัวเข้ารหัสอัตโนมัติแบบแปรผัน เครือข่ายก่อกำเนิดแบบปรปักษ์และการประยุกต์ใช้ เครือข่ายก่อกำเนิดแบบปรปักษ์ที่มีเงื่อนไข', 'Attention Mechanisms, Transformers, Generative Pre-trained Transformers (GPTs), Autoencoders and Applications, Variational Autoencoders (VAEs), Generative Adversarial Networks (GANs), Conditional Generative Adversarial Networks (CGANs)', true, now(), now()),
  ('INT282', 'สถิติสำหรับวิทยาการข้อมูล', 'Statistics for Data Science', 1, 'ความรู้เบื้องต้นเกี่ยวกับสถิติเพื่อการวิเคราะห์ข้อมูล การวิเคราะห์ข้อมูลเชิงสำรวจโดยใช้ความรู้ทางสถิติ สถิติเชิงอนุมาน การวิเคราะห์การถดถอย การทดสอบสมมติฐาน การวิเคราะห์สหสัมพันธ์ การวิเคราะห์ความแปรปรวน(อะโนวา) การทดสอบนัยสำคัญ การทดสอบ Z-test การทดสอบ t-test การทดสอบ F-test, การเขียนโปรแกรมสำหรับการวิเคราะห์ทางสถิติ', 'Introduction to statistics for data analysis, exploratory data analysis using statistical knowledge, inferential statistics, regression analysis, hypothesis testing, correlation analysis, analysis of variance (ANOVA), significance testing, Z-test, t-test, F-test, programming for statistical analyses', true, now(), now()),
  ('INT285', 'การแสดงผลข้อมูลด้วยภาพขั้นสูง', 'Advanced Data Visualization', 2, 'เทคนิคจินตทัศน์ข้อมูลขั้นสูง การเขียนโปรแกรมสำหรับจินตทัศน์ข้อมูล การจัดการและเตรียมข้อมูลสำหรับการสร้างจินตทัศน์ข้อมูล ไลบรารีที่เกี่ยวกับจินตทัศน์ข้อมูล จินตทัศน์ข้อมูลสำหรับข้อมูลมิติสูง จินตทัศน์ข้อมูลสำหรับข้อมูลอนุกรมเวลา จินตทัศน์ข้อมูลสำหรับข้อมูลเชิงพื้นที่ภูมิศาสตร์ จินตทัศน์ข้อมูลสำหรับข้อมูลเชิงเครือข่าย จินตทัศน์ข้อมูลสำหรับข้อมูลเชิงธุรกิจ จินตทัศน์ข้อมูลเพื่อการตัดสินใจ จินตทัศน์ข้อมูลสำหรับแดชบอร์ดเชิงโต้ตอบ', 'Advanced data visualization techniques, programing for data visualization, data manipulation and preparation for visualization, data visualization libraries, visualizing high- dimensional data, time series visualization, geospatial data visualization, network visualization, business data visualization, data visualization for decision-making, data visualization for interactive dashboard', true, now(), now()),
  ('INT290', 'เอสคิวแอลขั้นสูง', 'Advanced SQL', 1, 'การเขียนคำสั่งเอสคิวแอลที่ประกอบด้วยซับคิวรี่ที่ซ้อนอยู่ในคำสั่ง SELECT, INSERT, UPDATE,', 'DELETE. การเขียนซับคิวรี่ที่มีความเกี่ยวเนื่องกัน (correlated subquery) การรวมข้อมูลจากหลายตาราง ด้วย outer join และรวมตารางตัวเอง (self join) การสร้างวิว และ materialized view Nested Queries (Subqueries)/Correlated Nested Queries, Outer joins/Self Joins, View/Materialized View', true, now(), now()),
  ('INT291', 'แนวคิดและการออกแบบฐานข้อมูลเชิงกายภาพ', 'Physical Database Concepts and Design', 1, 'โครงสร้างภายในของระบบฐานข้อมูล แนวคิดและการออกแบบฐานข้อมูลเพื่อประสิทธิภาพของฐานข้อมูลโดยการทำดรรชนี แนวคิดการทำดีนอร์มอลไลซ์เบื้องต้น การแบ่งส่วนตาราง การแบ่งคลัสเตอร์ การทำซ้ำฐานข้อมูล แนวคิดเบื้องต้นของฐานข้อมูลแบบกระจาย และบทบาทของผู้บริหารฐานข้อมูล', 'Internal database structure, database design and concepts for database performance; indexing, basic denormalization concepts, table partitioning, clustering, database replication, basic distributed database concepts and database administration role.', true, now(), now()),
  ('INT292', 'แนวคิดการประมวลผลคิวรี', 'Query Processing Concepts', 1, 'แนวคิดการประมวลผลคิวรี ขั้นตอนการประมวลผลคิวรี การแยกส่วนคิวรี การทำออปติไมซ์เซชันการสร้างโค้ด การดำเนินการคิวรี และการใช้เครื่องมือหรือคำสั่งในการตรวจสอบการประมวลผลคิวรี', 'Query processing concepts; steps for query processing; query decomposition, optimization, code generation, query execution and using tools or commands for checking query processing.', true, now(), now()),
  ('INT293', 'การประมวลผลทรานแซกชัน', 'Transaction Processing', 1, 'แนวคิดการประมวลผลทรานแซกซัน คุณสมบัติของทรานแซกชัน การควบคุมการประมวลผลทรานแซกชันที่เกินในเวลาเดียวกัน และการกู้คืนฐานข้อมูล', 'DBMS Transaction Processing Concept, Properties of transaction, Concurrency control and Database Recovery', true, now(), now()),
  ('INT294', 'คลังข้อมูลและการประมวลผลเชิงวิเคราะห์แบบออนไลน์', 'Data Warehouse and OLAP', 2, 'แนวคิดคลังข้อมูล สถาปัตยกรรมและองค์ประกอบหลักของคลังข้อมูล การออกแบบคลังข้อมูลแบบจำลองข้อมูลสำหรับคลังข้อมูล การปรับค่าที่เหมาะสมให้กับคลังข้อมูล การประมวลผลเชิงวิเคราะห์แบบออนไลน์ ส่วนต่อขยายโอแอลเอพีต่อภาษาเอสคิวแอลมาตรฐาน', 'Data Warehouse Concepts, Architecture and main components of a data warehouse. Data Warehouse Design, Data modeling for data warehouses. Optimizing a data warehouse. Online Analytical Processing (OLAP), OLAP Extensions to the SQL Standard', true, now(), now()),
  ('INT295', 'การระบุตัวตนและการอนุญาตใช้งานฐานข้อมูล', 'Database Authentication and Authorization', 1, 'ความมั่นคงของฐานข้อมูล การควบคุมความปลอดภัยบนคอมพิวเตอร์ การควบคุมการเข้าถึงตามดุลยพินิจและการควบคุมการเข้าถึงที่จำเป็น การพิสูจน์ตัวตน การอนุญาต การเข้ารหัส', 'Database security, Conmputer-based security controls, Discretionary access control and mandatory Access control, Authentication, Authorization, Encryption', true, now(), now()),
  ('INT296', 'สถาปัตยกรรมข้อมูลขนาดใหญ่', 'Big Data Architecture', 2, 'ความรู้เบื้องต้นเกี่ยวกับข้อมูลขนาดใหญ่ แพลตฟอร์มข้อมูลขนาดใหญ่ การนำเข้าและการรวมข้อมูลไปป์ไลน์ข้อมูลและการจัดการเวิร์กโฟลว์ เฟรมเวิร์กการประมวลผลข้อมูลขนาดใหญ่ การประมวลผลแบบแบตช์ การประมวลผลแบบเรียลไทม์ การประมวลผลแบบสตรีม', 'Introduction to big data architecture, big data platforms, data ingestion and integration, data pipelines and workflow management, distributed programming, big data processing frameworks, batch processing, real-time processing, stream processing', true, now(), now()),
  ('INT297', 'ฐานข้อมูลโนเอสคิวแอล', 'NoSQL Database', 2, 'แนวคิดฐานข้อมูลแบบกระจาย ชนิดของระบบฐานข้อมูลแบบกระจาย สถาปัตยกรรมฐานข้อมูลแบบกระจาย ความรู้เบื้องต้นเกี่ยวกับระบบโนเอสคิวแอล ทฤษฎี CAP ประเภทของระบบโนเอสคิวแอล', 'Distributed database concepts, Types of distributed database systems, Distributed database architectures, Introduction to NoSQL systems, The CAP theorem, Categories of NoSQL Systems: Document-based NoSQL systems, NoSQL key-value stores, Column-based or wide column NoSQL systems, and Graph-base NoSQL system.', true, now(), now()),
  ('INT300', 'ระเบียบวิธีวิจัย', 'Research Methodology', 3, 'การสังเกต กระบวนการในการทำวิจัย การทบทวนวรรณกรรมที่เกี่ยวข้อง การอ่านและเขียนบทคัดย่อการตั้งคำถามวิจัย การสร้างโมเดลวิจัย การเขียนข้อเสนอโครงการวิจัย การนำเสนอโครงการวิจัย', 'Observation, research process, literature review, reading and writing abstracts, formulating research questions, design thinking, building research model, writing research proposal, presenting research projects', true, now(), now()),
  ('INT301', 'ระบบสารสนเทศเพื่อการจัดการ', 'Management Information Systems', 3, 'การจัดการองค์กรดิจิทัล ความรู้เบื้องต้นเกี่ยวกับยุคสารสนเทศ ระบบสารสนเทศในองค์กร การจัดการและกลยุทธ์ จริยธรรมและประเด็นทางสังคม การออกแบบองค์กรใหม่โดยใช้ระบบสารสนเทศ การจัดการ กระบวนการทำงาน การว่าจ้างคนภายนอกมาทำงาน ความเข้าใจคุณค่าของธุรกิจของระบบและการจัดการ การเปล่ียนแปลงเศรษฐศาสตร์ของเทคโนโลยีสารสนเทศ และการจัดการศูนย์ข้อมูล', 'Managing the digital firm, introduction to information age, information systems in the enterprise, management and strategy, ethics and social issues, redesign the organization with information system, managing operation, outsourcing, understanding the business value of systems and managing change, information technology economics, and data center management', true, now(), now()),
  ('INT302', 'การบริหารบริการเทคโนโลยีสารสนเทศ', 'Information Technology Services Management', 3, 'การบริหารบริการด้านเทคโนโลยีสารสนเทศในองค์กร การจัดหา/การเลือกผู้ให้บริการ ผู้ใช้ พฤติกรรมองค์กร และการบริหารองค์กร ข้อตกลงระดับการให้บริการ เทคโนโลยีและเทคนิคเพื่อการให้บริการ การบริหารบุคลากรด้านเทคโนโลยีสารสนเทศ การคิดต้นทุนของการให้บริการ ปัจจัยหลักของความสำเร็จตัวอย่างกรณีศึกษาของหน่วยงานบริการเทคโนโลยีสารสนเทศ', 'Management of Information Technology services in an enterprise; acquisition/sourcing, users, organization behavior and organization management, service level agreement, techniques and technology for Information Technology services, Information Technology human resource management cost estimation, critical success factors case studies of Information Technology services organization', true, now(), now()),
  ('INT310', 'การจัดการกระบวนการทางธุรกิจ', 'Business Process Management', 3, 'พื้นฐานของการจัดการกระบวนการทางธุรกิจ การกำหนดและออกแบบกระบวนการ การค้นพบกระบวนการ ภาษาและเทคนิคการจำลองกระบวนการ การวิเคราะห์กระบวนการเชิงคุณภาพ การวิเคราะห์กระบวนการเชิงปริมาณ การวิเคราะห์การไหลและการจำลองสถานการณ์ การออกแบบใหม่กระบวนการ การพัฒนาและการดำเนินกระบวนการ การเฝ้าสังเกตและการควบคุมกระบวนการ ความชาญฉลาดของกระบวนการ การทำเหมืองกระบวนการ', 'Introduction to business process management, process identification and design, process discovery, modeling languages and techniques, qualitative process analysis, quantitative process analysis, flow analysis and simulation, process redesign, process implementation and execution, process monitoring and controlling, process intelligence, process mining.', true, now(), now()),
  ('INT311', 'ผู้ประกอบการเทคโนโลยีสารสนเทศ', 'Information Technology Entrepreneurship', 3, 'กระบวนการในการเริ่มต้นเป็นผู้ประกอบการ การประสบความสำเร็จของผู้ประกอบการ การประเมินและการตระหนักถึงโอกาสของธุรกิจ กลยุทธ์สำหรับก่อตั้งและพัฒนาการลงทุนทางธุรกิจสำหรับผู้ประกอบการรูปแบบของการลงทุนแบบใหม่ ๆ การลงทุนสำหรับวิสาหกิจขนาดกลางและขนาดย่อม การลงทุนในองค์กรที่มีขนาดใหญ่ขึ้น', 'Entrepreneurial opportunity recognition and evaluation, strategies for establishing and developing successful entrepreneurial business ventures, newly formed ventures, small to medium size ventures, entrepreneurial ventures within larger organizations', true, now(), now()),
  ('INT312', 'ปฏิบัติการระบบวางแผนทรัพยากรวิสาหกิจ', 'Enterprise Resource Planning Workshop', 3, 'แนวคิดการวางแผนทรัพยากรวิสาหกิจ หลักเบื้องต้นการเงินการบัญชี การสร้างระบบบัญชีทั่วไปเบื้องต้น การบริหารระบบ สร้างสมุดลงบัญชี งบประมาณ รายงานสถานะการเงิน การบริหารความมั่นคงของระบบการใช้งานพร้อมกัน การจัดการด้านรายงาน การจัดพิมพ์ ลำดับของเอกสาร และตัวเลือกโปรไฟล์', 'Enterprise resource planning (ERP) concepts, fundamental of financial accounting, basic implementation of general ledger, system administration, creating set of books, journals, budgeting, financial statement reporting, security management, concurrent programs and reports management, printer management, profile options and document sequences management', true, now(), now()),
  ('INT313', 'ปฏิบัติการการจัดการแบบซัพพลายเชน', 'Supply Chain Management Workshop', 3, 'ความรู้หลักการการบริหารเครือข่ายผู้ผลิต รูปแบบการดำเนินการจัดซื้อจนถึงการชำระ ระบบสนับสนุนในการซื้อและชำระโดยเน้นตามกระบวนการในขั้นตอนต่าง ๆ กระบวนการจัดหา จัดซื้อ การชำระ ผู้จำหน่าย รายชื่อผู้จำหน่ายที่รับรอง การสร้างเอกสารในกระบวนการโดยอัตโนมัติ ความมั่นคงของของเอกสารขั้นตอนการอนุมัติ การตั้งคลังสินค้า องค์ประกอบ สินค้าและชื่อหน่วยสินค้า', 'Supply chain management (SCM) concepts, basic implementation of procurement to pay solutions, the process based functionality supported in purchasing and payables, purchasing process, procurement process, payables process, suppliers, approved supplier lists, requisitions, automatic document creation, document security, routing, approvals, basic inventory and purchasing setups: locations, inventory organizations, units of measure and items', true, now(), now()),
  ('INT330', 'หลักการและแนวปฏิบัติของเดฟออปส์', 'DevOps: Principles and Practices', 3, 'การเรียบเรียงการทำงานของคอนเทนเนอร์ด้วยคูเบอร์เนตีส องค์ประกอบของระบบ การจัดการคลัสเตอร์ อินเกรส ระบบดีพลอยเมนท์ การจัดการโครงสร้างพื้นฐานด้วยการเขียนโค้ดเทร์ราฟอร์ม การสั่งสร้างโครงสร้างพื้นฐาน การรักษาสถานะของระบบ', 'Container orchestration using Kubernetes, components, cluster management, ingress, deployments; IaC with Terraform, deploying infrastructure, Terraform state', true, now(), now()),
  ('INT331', 'การพัฒนาแอปพลิเคชันแบบคลาวด์เนทีฟ', 'Cloud Native Application Development', 3, 'การให้บริการโครงสร้างพื้นฐานคลาวด์ กระบวนการพัฒนา ออกแบบ โครงสร้างพื้นฐาน การทดสอบความต้องการการพัฒนา และการติดตั้งแอปพลิเคชันบนคลาวด์', 'Cloud native infrastructure service, methodology for building software-as-a-service applications, designing cloud native applications, the infrastructure applications, cloud native deployment, testing cloud native infrastructure, application requirements on infrastructure, implementing cloud native infrastructure', true, now(), now()),
  ('INT332', 'การพัฒนาและติดตั้งระบบเทคโนโลยีสารสนเทศ', 'Information Technology System Implementation', 3, 'ปฏิบัติการให้บริการระบบเทคโนโลยีสารสนเทศ การพัฒนา สร้างระบบเทคโนโลยีสารสนเทศเครือข่าย โครงสร้างพื้นฐาน ตามมาตรฐานการพัฒนาระบบเครือข่ายและเทคโนโลยีสารสนเทศ', 'A hands-on coverage of networking and IT services technologies, practical experience in implementing many concepts in networking and IT services by creating their own configuring switches, server and other equipment, real-world implementations of many IT standards.', true, now(), now()),
  ('INT333', 'บล็อกเชนเบื้องต้น', 'Introduction to Blockchain', 3, 'บล็อกเชนเบื้องต้น บัญชีแยกประเภทแบบกระจาย คุณสมบัติเบื้องต้น การพิสูจน์งาน บัญชีแยกประเภทธุรกรรมทนทาน ประเด็นความเป็นส่วนตัว ประเด็นการปรับขนาดได้ บล็อกเชนในรูปแบบแพล็ตฟอร์ม สมาร์ตคอนแทรค การประยุกต์ใช้บล็อกเชน สกุลเงินคริปโต เทคนิคทางเลือกสำหรับการพิสูจน์งานการวิเคราะห์โพรโทคอลบล็อกเชน', 'Introduction to blockchain, distributed ledger, basic properties, proof of work, robust transaction ledgers, privacy issues, scalability issues, blockchain as a platform, smart contracts, blockchain applications, cryptocurrencies, alternative techniques to proof of work, analysis of blockchain protocols.', true, now(), now()),
  ('INT334', 'การบริหารโครงสร้างพื้นฐานเทคโนโลยีสารสนเทศ', 'Information Technology Infrastructure Management', 3, 'ภาพบูรณาการของระบบเทคโนโลยีสารสนเทศ ทั้งด้านฮาร์ดแวร์ บริการและโครงสร้างพื้นฐานประเภทต่าง ๆ การจัดหาระบบเทคโนโลยีสารสนเทศ ผ่านกรณีศึกษา ศึกษาความต้องการ เขียนข้อเสนอโครงการ ข้อกำหนดความต้องการ การนำเสนอโครงการ ประเด็นต่าง ๆ ในการจัดหาระบบเทคโนโลยีสารสนเทศ แนวทางการบริหารโครงการ การทดสอบระบบ การบำรุงรักษาและประเด็นองค์กร', 'Integrated view of Information Technology hardware, services and infrastructure management, Information Technology procurement process through a case study, requirements gathering, project proposal, requirement specifications, project presentation, Information Technology acquirement issues: project management, testing, maintenance and organizational issues', true, now(), now()),
  ('INT341', 'การบริหารโครงการซอฟต์แวร์', 'Software Project Management', 3, 'ระเบียบวิธีการที่เป็นระบบในการเริ่มต้น วางแผน ดำเนินการ ควบคุม และปิดโครงงาน การประเมินแรงงานและค่าใช้จ่ายในการพัฒนาซอฟต์แวร์ การบริหารคนและการจัดทีมงาน การบริหารความเสี่ยงเครื่องมือในการบริหารโครงงาน', 'The course covers a systematic methodology for initiating, planning, executing, controlling, and closing projects. Effort and cost estimation in software development, managing people and organizing teams, risk management, project management tools', true, now(), now()),
  ('INT342', 'การพัฒนาซอฟต์แวร์แบบกระจาย', 'Distributed Software Development', 2, 'หลักการเบื้องต้นการพัฒนาซอฟต์แวร์แบบกระจาย ปัจจัยหลักของการพัฒนาซอฟต์แวร์แบบกระจายการจัดการความเสี่ยง การเลือกกระบวนการพัฒนา การออกแบบสถาปัตยกรรม การออกแบบส่วนต่อประสานระหว่างมอดูล การแบ่งงานและการจัดตารางงานสำหรับบุคลากรที่อยู่ในพื้นท่ีเดียวกันและนอกพื้นที่', 'Introduction to distributed software development, key factors for distributed software development, risk management, software development process selection, architectural design, module interface design, work allocation and assignment both for local and global staff', true, now(), now()),
  ('INT343', 'ปฏิบัติการพัฒนาโมไบล์แอปพลิเคชันแบบผสม', 'Hybrid Mobile Application Development Workshop', 3, 'แนะนำการพัฒนาโมล์แอปพลิเคชันแบบผสม เขียนโปรแกมจาวาสคริปต์สมัยใหม่ เข้าใจหลักการทำงานของรีแอคเนทีฟ การใช้งานกับคอมโพเน้นท์และสไตล์ การใช้งานการเนวิเกชั่น การใช้งานคอมโพเน้นท์เคลื่อนไหวของรีแอคเนทีฟ การนำสถาปัตยกรรมฟลักซ์กับดีดักซ์ไปใช้งาน การใช้งานคอมโพเน้นท์และเอพีไอที่ใช้ข้ามหรือเฉพาะเจาะจงแพลตฟอร์ม การใช้งานร่วมกับฟอร์มและการคงอยู่ของข้อมูล และการนำแอปพลิเคชันขึ้นสู่แอปเปิลแอปสโตร์ หรือกูเกิลเพลย์', 'Introduction to hybrid mobile application development, writing modern JavaScript, understanding how react native works, working with components and styles, working with navigations, working with animating react native components, implementing flux architecture with Redux, working with cross/specific-platform components and APIs, working with form and data persistence and deploying mobile application to Apple app store or Google play.', true, now(), now()),
  ('INT344', 'การพัฒนาระบบอินเทอร์เน็ตแห่งสรรพสิ่ง', 'Internet of Things Development', 3, 'แนวคิดและหลักการของอินเทอร์เน็ตแห่งสรรพสิ่ง แพลตฟอร์มการพัฒนาอินเทอร์เน็ตแห่งสรรพสิ่งการพัฒนาโปรแกรมของอินเทอร์เน็ตแห่งสรรพสิ่ง เทคโนโลยีการเชื่อมต่อเครือข่ายในอินเทอร์เน็ตแห่งสรรพสิ่งการจัดการความมั่นคงปลอดภัยในระบบนิเวศอินเทอร์เน็ตแห่งสรรพสิ่ง', 'Concept and Principle of Internet of Things (IoT), Internet of Things Development Platform, Internet of Things Programming, Networking Technologies in Internet of Things, Security Management of the Internet of Things Ecosystem', true, now(), now()),
  ('INT370', 'การประมวลผลภาษาธรรมชาติประยุกต์', 'Applied Natural Language Processing', 3, 'การประมวลผลภาษาธรรมชาติเบื้องต้น การเตรียมข้อความ การแท็กส่วนของคำพูด การแจกแจงรูปประโยค การรู้จำชื่อเฉพาะ การแทนคำและการเข้ารหัสคำ โมเดลภาษา การวิเคราะห์ความรู้สึก การจำแนกประเภทข้อความ การแปลภาษาด้วยเครื่อง การสกัดสารสนเทศ ระบบตอบคำถาม การสรุปข้อความ การสร้างข้อความ', 'Introduction to Natural Language Processing, Text Preprocessing, Part-of-Speech Tagging, Syntactic Parsing, Named Entity Recognition (NER), Word Representations and Word Embeddings, Language Models, Sentiment Analysis, Text Classification, Machine Translation, Information Extraction, Question Answering Systems, Text Summarization, Text Generation', true, now(), now()),
  ('INT371', 'คอมพิวเตอร์วิชันประยุกต์', 'Applied Computer Vision', 3, 'คอมพิวเตอร์วิชันเบื้องต้น การเตรียมภาพก่อนการประมวลผล การเสริมข้อมูลภาพ การเรียนรู้เชิงลึกสำหรับคอมพิวเตอร์วิชัน การจำแนกประเภทรูปภาพ การตรวจจับวัตถุและการประยุกต์ใช้ การแบ่งส่วนรูปภาพและการประยุกต์ใช้ การแบ่งส่วนเชิงความหมาย การแบ่งส่วนวัตถุ การสร้างภาพ การแปลงภาพประเภทหนึ่งไปเป็นภาพอีกประเภทหนึ่ง การเขียนคำบรรยายภาพ การรู้จำใบหน้า', 'Introduction to Computer Vision, Image Preprocessing, Image Augmentation, Deep Learning for Computer Vision, Image Classification, Object Detection and Applications, Image Segmentation and Applications, Semantic Segmentation, Instance Segmentation, Image Generation, Image-to-Image Translations, Image Captioning, Face Recognition', true, now(), now()),
  ('INT380', 'การวิเคราะห์ข้อมูลขนาดใหญ่', 'Big Data Analytics', 2, 'นิยามและคุณลักษณะของข้อมูลขนาดใหญ่ พื้นฐานเกี่ยวกับแนวคิดการคำนวณแบบกระจาย แนะนำเกี่ยวกับ MapReduce การเตรียมข้อมูลก่อนการวิเคราะห์ข้อมูลขนาดใหญ่ การวิเคราะห์ข้อมูลเชิงสำรวจสำหรับข้อมูลขนาดใหญ่ ขั้นตอนวิธีการเรียนรู้แบบเพิ่มขึ้นและการเรียนรู้แบบออนไลน์ แนวคิดการเรียนรู้เครื่องในการวิเคราะห์ข้อมูลขนาดใหญ่ แนะนำเกี่ยวกับการวิเคราะห์ข้อมูลขนาดใหญ่ในรูปแบบคลาวด์ ความท้าทายและข้อพิจารณาในการประมวลผลข้อมูลขนาดใหญ่', 'Definition and characteristics of big data, basics of distributed computing concepts, introduction to MapReduce, data preprocessing for big data analytics, exploratory data analysis for big data, incremental and online learning algorithms, introduction to machine learning in big data analytics, introduction to cloud-based big data analytics, challenges and considerations in big data processing', true, now(), now()),
  ('INT381', 'ธุรกิจอัจฉริยะ', 'Business Intelligence', 2, 'หลักการของธุรกิจอัจฉริยะ การจัดการคลังข้อมูลสำหรับธุรกิจอัจฉริยะ การรวบรวมข้อมูล รายงานและการทำให้เห็นได้สำหรับธุรกิจอัจฉริยะ การวิเคราะห์เชิงพรรณนา การวิเคราะห์เชิงคาดการณ์ การตัดสินใจที่มีการใช้ข้อมูลเป็นพื้นฐาน การจัดการความรู้ เครื่องมือและการนำไปใช้ การสร้างผลิตภัณฑ์ข้อมูลที่รองรับการขยายตัวได้', 'Concepts of business intelligence, management of data warehouses for business intelligence, information gathering, reporting and visualization for business intelligence, descriptive analytics, predictive analytics, data-driven decision-making, knowledge management, tool and implementation, building data products at scale', true, now(), now()),
  ('INT390', 'ปฏิบัติการการโปรแกรมฐานข้อมูล', 'Database Programming Workshop', 3, 'แนะนำการใช้ภาษาพีแอล/เอสคิวแอล การประกาศตัวแปร การเขียนคำสั่งที่สามารถดำเนินการ การเขียนคำสั่งพีแอล/เอสคิวแอล การเขียนคำสั่งควบคุมการทำงาน การทำงานกับชนิดข้อมูลแบบคอมโฟสิต การใช้เคอเซอร์แบบชัดเจน การจัดการความผิดพลาด การเขียนสโตร์โพรซีเยอร์และสโตร์ฟังก์ชัน การสร้างและใช้งานกับชุดโปรแกรม การใช้คำสั่งเอสคิวแอลแบบไดนามิก และการสร้างทริกเกอร์', 'Introduction to PL/SQL, Declaring PL/SQL Variables, Writing Executable Statements, Writing PL/SQL Statements, Writing Control Statements, Working with Composite Data Types, Using Explicit Cursors, Handling Exceptions, Creating Stored Procedures and Functions, Creating and working with Packages, Using Dynamic SQL and Creating Triggers.', true, now(), now()),
  ('INT401', 'หัวข้อพิเศษทางเทคโนโลยีสารสนเทศ', 'Special Topic in Information Technology', 1, 'วิชานี้เปิดโอกาสให้นักศึกษาสำรวจหัวข้อที่ทันสมัยหรือเฉพาะเจาะจงทางด้านเทคโนโลยีสารสนเทศสอนโดยคณาจารย์ผู้เชี่ยวชาญหรือมืออาชีพในสาขา หลักสูตรนี้เสนอประสบการณ์การเรียนรู้ที่ขยายความรู้และทักษะของนักศึกษา', 'This course provides students with an opportunity to explore cutting-edge or specific topics in information technology. Taught by expert faculty or professionals in the field, this course offers an enriched learning experience that broaden the students knowledge and skills.', true, now(), now()),
